function SloForgePure(){
  var NINES = [
    {pct:90,     label:'一个九 90%'},
    {pct:99,     label:'两个九 99%'},
    {pct:99.5,   label:'99.5%'},
    {pct:99.9,   label:'三个九 99.9%'},
    {pct:99.95,  label:'99.95%'},
    {pct:99.99,  label:'四个九 99.99%'},
    {pct:99.995, label:'99.995%'},
    {pct:99.999, label:'五个九 99.999%'}
  ];

  // Google SRE Workbook 第 5 章推荐的多窗口多燃尽率告警
  var ALERT_SPEC = [
    {sev:'页面告警 Page',   longHours:1,  shortHours:1/12, consumed:0.02, note:'1 小时内烧掉 2% 预算，立即呼叫值班'},
    {sev:'页面告警 Page',   longHours:6,  shortHours:0.5,  consumed:0.05, note:'6 小时内烧掉 5% 预算，持续性事故'},
    {sev:'工单告警 Ticket', longHours:24, shortHours:2,    consumed:0.10, note:'1 天内烧掉 10% 预算，下个工作日处理'},
    {sev:'工单告警 Ticket', longHours:72, shortHours:6,    consumed:0.10, note:'3 天内烧掉 10% 预算，慢性劣化'}
  ];

  function num(v, name){
    var n = Number(v);
    if (!isFinite(n)) return {error:name + ' 不是合法数字：' + v};
    return {value:n};
  }

  function parseObjective(v){
    var s = String(v == null ? '' : v).trim().replace(/%$/, '');
    var mn = /^([0-9]+)\s*(?:个\s*9|个\s*九|nines?)$/i.exec(s);
    if (mn){
      var k = parseInt(mn[1], 10);
      if (k < 1 || k > 9) return {error:'“九”的个数需在 1..9'};
      return {value:100 - Math.pow(10, 2 - k)};
    }
    var n = Number(s);
    if (!isFinite(n)) return {error:'无法解析可用性目标：' + v};
    if (n <= 0 || n >= 100) return {error:'可用性目标必须落在 (0, 100) 之间，当前 ' + n};
    return {value:n};
  }

  function ninesLabel(pct){
    for (var i = 0; i < NINES.length; i++){
      if (Math.abs(NINES[i].pct - pct) < 1e-9) return NINES[i].label;
    }
    return pct + '%';
  }

  function fmtDuration(sec){
    if (!isFinite(sec)) return '∞';
    if (sec < 0) return '0 秒';
    if (sec < 1) return (Math.round(sec * 1000)) + ' 毫秒';
    var s = sec;
    var d = Math.floor(s / 86400); s -= d * 86400;
    var h = Math.floor(s / 3600);  s -= h * 3600;
    var m = Math.floor(s / 60);    s -= m * 60;
    var out = [];
    if (d) out.push(d + ' 天');
    if (h) out.push(h + ' 小时');
    if (m) out.push(m + ' 分');
    if (s > 0.0005 || !out.length) out.push((Math.round(s * 10) / 10) + ' 秒');
    return out.join(' ');
  }

  // 目标可用性 → 各时间窗口内允许的不可用时长
  function budget(objectivePct, windowDays){
    var po = parseObjective(objectivePct);
    if (po.error) return {error:po.error};
    var wd = Number(windowDays);
    if (!isFinite(wd) || wd <= 0 || wd > 3650) return {error:'统计窗口需为 0..3650 天'};
    var slo = po.value / 100;
    var unavailable = 1 - slo;
    var windowSec = wd * 86400;
    var allowed = windowSec * unavailable;
    return {
      error:null,
      objectivePct:po.value, label:ninesLabel(po.value),
      windowDays:wd, windowSeconds:windowSec,
      unavailableFraction:unavailable,
      allowedSeconds:allowed, allowedText:fmtDuration(allowed),
      perDaySeconds:86400 * unavailable, perDayText:fmtDuration(86400 * unavailable),
      perWeekSeconds:604800 * unavailable, perWeekText:fmtDuration(604800 * unavailable),
      perMonthSeconds:2592000 * unavailable, perMonthText:fmtDuration(2592000 * unavailable),
      perYearSeconds:31536000 * unavailable, perYearText:fmtDuration(31536000 * unavailable)
    };
  }

  // 由实际请求量计算预算消耗
  function consume(totalRequests, badRequests, objectivePct, windowDays){
    var b = budget(objectivePct, windowDays || 30);
    if (b.error) return {error:b.error};
    var t = num(totalRequests, '总请求数'); if (t.error) return {error:t.error};
    var bad = num(badRequests, '失败请求数'); if (bad.error) return {error:bad.error};
    if (t.value <= 0) return {error:'总请求数必须大于 0'};
    if (bad.value < 0) return {error:'失败请求数不能为负'};
    if (bad.value > t.value) return {error:'失败请求数不能超过总请求数'};
    var errorRate = bad.value / t.value;
    var budgetRequests = t.value * b.unavailableFraction;
    var usedPct = budgetRequests > 0 ? (bad.value * 100 / budgetRequests) : 0;
    var remainingPct = 100 - usedPct;
    var burn = b.unavailableFraction > 0 ? errorRate / b.unavailableFraction : 0;
    var status = usedPct >= 100 ? 'EXHAUSTED' : (usedPct >= 75 ? 'AT_RISK' : (usedPct >= 25 ? 'WATCH' : 'HEALTHY'));
    return {
      error:null, base:b,
      errorRatePct:errorRate * 100,
      availabilityPct:(1 - errorRate) * 100,
      budgetRequests:budgetRequests,
      usedRequests:bad.value,
      remainingRequests:budgetRequests - bad.value,
      usedPct:usedPct, remainingPct:remainingPct,
      burnRate:burn, status:status,
      meetsObjective:((1 - errorRate) * 100 >= b.objectivePct - 1e-12)
    };
  }

  // 按当前燃尽率，剩余预算还能烧多久
  function timeToExhaust(burnRate, windowDays, remainingPct){
    var br = Number(burnRate), wd = Number(windowDays), rp = Number(remainingPct);
    if (!isFinite(br) || br <= 0) return {error:'燃尽率必须大于 0', hours:Infinity};
    if (!isFinite(wd) || wd <= 0) return {error:'统计窗口必须大于 0'};
    if (!isFinite(rp) || rp < 0) return {error:'剩余预算百分比不能为负'};
    var hours = (rp / 100) * wd * 24 / br;
    return {error:null, hours:hours, text:fmtDuration(hours * 3600)};
  }

  // 多窗口多燃尽率告警阈值
  function multiWindow(objectivePct, windowDays){
    var b = budget(objectivePct, windowDays || 30);
    if (b.error) return {error:b.error};
    var rows = [];
    for (var i = 0; i < ALERT_SPEC.length; i++){
      var a = ALERT_SPEC[i];
      var burn = a.consumed * b.windowDays * 24 / a.longHours;
      var thr = burn * b.unavailableFraction;
      rows.push({
        sev:a.sev, longHours:a.longHours, shortHours:a.shortHours,
        consumedPct:a.consumed * 100, burnRate:burn,
        thresholdErrorRatePct:Math.min(thr * 100, 100),
        capped:(thr > 1),
        note:a.note,
        longLabel:(a.longHours >= 24 ? (a.longHours / 24) + ' 天' : a.longHours + ' 小时'),
        shortLabel:(a.shortHours < 1 ? Math.round(a.shortHours * 60) + ' 分钟' : a.shortHours + ' 小时')
      });
    }
    return {error:null, base:b, rows:rows};
  }

  // 复合可用性：串行依赖相乘，冗余副本 1-(1-a)^n
  function composite(list){
    if (!list || !list.length) return {error:'请至少输入一个依赖的可用性'};
    var prod = 1, parsed = [];
    for (var i = 0; i < list.length; i++){
      var p = parseObjective(list[i]);
      if (p.error) return {error:'第 ' + (i+1) + ' 项：' + p.error};
      parsed.push(p.value);
      prod *= p.value / 100;
    }
    return {error:null, items:parsed, serialPct:prod * 100,
            serialDowntimePerMonth:fmtDuration(2592000 * (1 - prod))};
  }
  function redundant(objectivePct, replicas){
    var p = parseObjective(objectivePct);
    if (p.error) return {error:p.error};
    var n = Number(replicas);
    if (!isFinite(n) || n < 1 || n > 50 || Math.floor(n) !== n) return {error:'副本数需为 1..50 的整数'};
    var f = 1 - p.value / 100;
    var avail = 1 - Math.pow(f, n);
    return {error:null, replicas:n, availabilityPct:avail * 100,
            downtimePerYear:fmtDuration(31536000 * Math.pow(f, n))};
  }

  function availabilityFromDowntime(downtimeSeconds, windowDays){
    var d = Number(downtimeSeconds), wd = Number(windowDays);
    if (!isFinite(d) || d < 0) return {error:'停机时长不能为负'};
    if (!isFinite(wd) || wd <= 0) return {error:'统计窗口必须大于 0'};
    var w = wd * 86400;
    if (d > w) return {error:'停机时长超过了统计窗口'};
    return {error:null, availabilityPct:(1 - d / w) * 100, label:ninesLabel((1 - d / w) * 100)};
  }

  function analyze(objectivePct, windowDays, totalRequests, badRequests){
    var b = budget(objectivePct, windowDays);
    if (b.error) return {error:b.error};
    var c = consume(totalRequests, badRequests, objectivePct, windowDays);
    if (c.error) return {error:c.error};
    var mw = multiWindow(objectivePct, windowDays);
    var tte = timeToExhaust(c.burnRate, b.windowDays, c.remainingPct);
    return {error:null, budget:b, consume:c, alerts:mw.rows, exhaust:tte, table:NINES};
  }

  var api = {NINES:NINES, ALERT_SPEC:ALERT_SPEC, parseObjective:parseObjective, ninesLabel:ninesLabel,
             fmtDuration:fmtDuration, budget:budget, consume:consume, timeToExhaust:timeToExhaust,
             multiWindow:multiWindow, composite:composite, redundant:redundant,
             availabilityFromDowntime:availabilityFromDowntime, analyze:analyze};
  if (typeof window !== 'undefined'){ window.__PURE__ = api; }
  if (typeof module !== 'undefined' && module.exports){ module.exports = {SloForgePure:SloForgePure}; }
  return api;
}
